import{_ as e,a,b as i}from"./chunks/setup-smartscreen-2.Bm2h4sAv.js";import{_ as r,a as n}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as l,o,c as h,ag as s}from"./chunks/framework.DTisvaUJ.js";const f=JSON.parse('{"title":"使用入门 — 在VRChat中使用语音识别与朗读","description":"从安装Mutelink到在VRChat中交流：介绍虚拟声卡、VRChat麦克风与OSC，以及快速设置。","frontmatter":{"title":"使用入门 — 在VRChat中使用语音识别与朗读","description":"从安装Mutelink到在VRChat中交流：介绍虚拟声卡、VRChat麦克风与OSC，以及快速设置。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"使用入门 — 在VRChat中使用语音识别与朗读 | Mutelink"}],["meta",{"property":"og:description","content":"从安装Mutelink到在VRChat中交流：介绍虚拟声卡、VRChat麦克风与OSC，以及快速设置。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"使用入门 — 在VRChat中使用语音识别与朗读 | Mutelink"}],["meta",{"name":"twitter:description","content":"从安装Mutelink到在VRChat中交流：介绍虚拟声卡、VRChat麦克风与OSC，以及快速设置。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}]]},"headers":[],"relativePath":"zh/guide/getting-started.md","filePath":"zh/guide/getting-started.md"}'),u={name:"zh/guide/getting-started.md"};function p(g,t,d,m,c,b){return o(),h("div",null,[...t[0]||(t[0]=[s('<h1 id="はじめかた" tabindex="-1">使用入门 <a class="header-anchor" href="#はじめかた" aria-label="Permalink to &quot;使用入门 {#はじめかた}&quot;">​</a></h1><p>以下步骤帮助你从安装开始在VRChat中交流。应用内部的设置由首次启动时的“快速设置”引导，本页主要介绍应用以外的准备。</p><h2 id="_1-vb-audio-virtual-cableを入れる" tabindex="-1">1. 安装VB-Audio Virtual Cable <a class="header-anchor" href="#_1-vb-audio-virtual-cableを入れる" aria-label="Permalink to &quot;1. 安装VB-Audio Virtual Cable {#_1-vb-audio-virtual-cableを入れる}&quot;">​</a></h2><p>这款免费软件可将朗读声音传入VRChat麦克风。只使用聊天框时可跳过。</p><ol><li>下载并安装<a href="https://vb-audio.com/Cable/" target="_blank" rel="noreferrer">VB-Audio Virtual Cable</a>。</li><li>确认Windows声音设置中出现“CABLE Input”和“CABLE Output”。未出现时请重启电脑。</li></ol><p>**请在安装Mutelink之前安装。**若安装时Mutelink已打开，请重启Mutelink。</p><p><img src="'+e+'" alt="Windows声音设置中的CABLE Input和CABLE Output"></p><h2 id="_2-mutelinkをインストールする" tabindex="-1">2. 安装Mutelink <a class="header-anchor" href="#_2-mutelinkをインストールする" aria-label="Permalink to &quot;2. 安装Mutelink {#_2-mutelinkをインストールする}&quot;">​</a></h2><ol><li>从<a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a>或<a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTH</a>下载安装程序（<code>Mutelink_x.x.x_x64-setup.exe</code>）。</li><li>运行安装程序，无需管理员权限。</li></ol><p>应用尚未进行代码签名，Windows可能提示“Windows已保护你的电脑”。点击“更多信息”，再点击“仍要运行”。</p><table tabindex="0"><thead><tr><th>① 点击“更多信息”</th><th>② 点击“仍要运行”</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="点击更多信息"></td><td><img src="'+i+'" alt="点击仍要运行"></td></tr></tbody></table><h2 id="_3-クイックセットアップを進める" tabindex="-1">3. 完成快速设置 <a class="header-anchor" href="#_3-クイックセットアップを進める" aria-label="Permalink to &quot;3. 完成快速设置 {#_3-クイックセットアップを進める}&quot;">​</a></h2><p>首次启动会打开“快速设置”。选择用途（语音交流、翻译、键盘输入、以字幕阅读对方发言、VR）后，将依次显示所需设置。</p><p>尤其需要注意以下三项。</p><ul><li><strong>麦克风</strong>：选择你实际说话使用的麦克风。不要选择“CABLE Output”，否则会识别朗读声音。</li><li><strong>扬声器</strong>：使用朗读时，同时选择传入VRChat的“CABLE Input”和自己听声音的扬声器或耳机。</li><li><strong>识别引擎与朗读声音</strong>：不确定时可查看<a href="/Mutelink-releases/zh/compare/speech-recognition">语音识别引擎对比</a>和<a href="/Mutelink-releases/zh/compare/voices">朗读声音对比</a>。以后也可修改。</li></ul><p>可在设置 &gt; 使用方式中重新运行快速设置。</p><h2 id="_4-vrchat側を設定する" tabindex="-1">4. 设置VRChat <a class="header-anchor" href="#_4-vrchat側を設定する" aria-label="Permalink to &quot;4. 设置VRChat {#_4-vrchat側を設定する}&quot;">​</a></h2><h3 id="声を流すとき" tabindex="-1">使用声音输出时 <a class="header-anchor" href="#声を流すとき" aria-label="Permalink to &quot;使用声音输出时 {#声を流すとき}&quot;">​</a></h3><p>在VRChat的设置 &gt; 音频中，将麦克风设为“CABLE Output”。</p><div class="warning custom-block"><p class="custom-block-title">不要保留“默认（Default）”</p><p>若保留“默认”，VRChat可能使用实际麦克风，将你的原声传给别人。请务必选择“CABLE Output”。</p></div><p>建议将VRChat麦克风保持开启（切换模式），避免朗读声音中途被截断。</p><p><img src="'+r+'" alt="将VRChat麦克风设为CABLE Output"></p><h3 id="チャットボックスだけで使うとき" tabindex="-1">只使用聊天框时 <a class="header-anchor" href="#チャットボックスだけで使うとき" aria-label="Permalink to &quot;只使用聊天框时 {#チャットボックスだけで使うとき}&quot;">​</a></h3><p>请将VRChat麦克风静音。否则你用于语音识别的声音会直接被对方听见。</p><h3 id="チャットボックスを使うとき" tabindex="-1">使用聊天框时 <a class="header-anchor" href="#チャットボックスを使うとき" aria-label="Permalink to &quot;使用聊天框时 {#チャットボックスを使うとき}&quot;">​</a></h3><p>启用VRChat的OSC（圆形菜单 &gt; Options &gt; OSC &gt; Enabled）。</p><p><img src="'+n+'" alt="启用VRChat的OSC"></p><h2 id="_5-使ってみる" tabindex="-1">5. 开始使用 <a class="header-anchor" href="#_5-使ってみる" aria-label="Permalink to &quot;5. 开始使用 {#_5-使ってみる}&quot;">​</a></h2><p>在主界面开启语音识别并对麦克风说话。识别结果会显示在屏幕上，确认后发送，也可设置自动发送。</p><p>点击设置右上角的“？”即可查看按钮和各项设置的说明。</p><p>如无法正常运行，请查看<a href="/Mutelink-releases/zh/help/troubleshooting">故障排除</a>。</p>',31)])])}const V=l(u,[["render",p]]);export{f as __pageData,V as default};
